# =================================================================
# ARCHIVO GENERADO AUTOMÁTICAMENTE: Indice de pobreza 
# Mapa tematico del indice de pobreza segun CONEVAL 
# =================================================================


# Capa: c_pobreza_0
LAYER
    NAME "c_pobreza_0"
    STATUS ON
    TYPE POLYGON
    CONNECTIONTYPE POSTGIS
    CONNECTION "host=mxsig-db port=5432 dbname=mdm6data user=postgres password=P0stgr3s"
    DATA "the_geom FROM (SELECT gid, the_geom, pobreza FROM coneval.indice_pobreza WHERE  pobreza<50) AS t1 USING UNIQUE gid USING SRID=900913"
    METADATA
        "wms_title" "c_pobreza_0"
        "wms_enable_request" "*"
    END
    CLASS
        NAME "c_pobreza_0"
        STYLE
            COLOR 255 255 255
            OUTLINECOLOR 60 60 60
            OPACITY 60
            WIDTH 0.8
        END
    END
END

